#pragma once
inline nlohmann::json checkTransmission(hb::gpu::SceneRenderer& renderer){
    using namespace hb::gpu;
    renderer.resize(64,64);renderer.setLights({});renderer.setShadows({});SceneFrame frame;frame.transmission=true;frame.ambient={0,0,0,1};
    const std::vector<std::uint32_t> triangles={0,1,2,0,2,3};
    const auto quad=[&](float left,float right,float z,std::array<float,3> normal=std::array<float,3>{0,0,1}){return renderer.createMesh({{{left,-.9f,z},normal},{{right,-.9f,z},normal},{{right,.9f,z},normal},{{left,.9f,z},normal}},triangles);};
    auto left=quad(-.9f,.9f,.8f),right=quad(-.05f,.05f,.7f),glass=quad(-.8f,.8f,.4f),tilted=quad(-.8f,.8f,.4f,{.8f,0,1});
    SceneMaterial red;red.unlit=true;red.color={1,0,0,1};SceneMaterial green=red;green.color={0,1,0,1};SceneMaterial clear;clear.volume={1,0,0,0};clear.roughness=0;clear.physical[2]=1;
    const auto render=[&](const SceneRenderer::Mesh& mesh,const SceneMaterial& material){renderer.begin(frame);renderer.draw(left,identity,identity,red);renderer.draw(right,identity,identity,green);renderer.captureTransmission();renderer.draw(mesh,identity,identity,material);return renderer.readPixels();};
    const auto center=(32*64+32)*4;auto thin=render(glass,clear);assert(thin[center]<5&&thin[center+1]>220);assert(renderer.bloomDispatches()==0&&renderer.transmissionTextureBytes()>0);
    const auto allocations=renderer.transmissionAllocations(),copies=renderer.transmissionCopies();clear.volume[1]=.8f;auto straight=render(tilted,clear);clear.physical[2]=1.5f;auto bent=render(tilted,clear);if(!(straight[center+1]>220&&bent[center]>150&&bent[center+1]<50))throw std::runtime_error("Refraction pixels: "+nlohmann::json({{"straight",{straight[center],straight[center+1]}},{"bent",{bent[center],bent[center+1]}}}).dump());clear.roughness=1;auto rough=render(tilted,clear);assert(rough[center+1]>bent[center+1]+30);assert(renderer.transmissionAllocations()==allocations&&renderer.transmissionCopies()==copies+3);
    SceneFrame crop=frame;crop.viewport={16,16,32,32};crop.scissor=std::array<float,4>{16,16,32,32};renderer.begin(crop);renderer.draw(right,identity,identity,green);renderer.captureTransmission();clear.roughness=0;clear.volume[1]=0;clear.physical[2]=1;renderer.draw(glass,identity,identity,clear);auto cropped=renderer.readPixels();assert(cropped[center+1]>220&&cropped[0]==0);
    auto texture=renderer.createTexture(1,1,{255,255,255,255});auto program=renderer.createProgram("","base.rgb=1;",{});rejects([&]{renderer.draw(glass,identity,identity,clear,{}, {},0,0,&program,std::vector<const SceneRenderer::Texture*>(15,&texture),std::vector<std::uint32_t>(15,0));});
    frame.bloom=SceneBloom{0,1,.5f,.5f};auto glowing=render(glass,clear);assert(glowing[center+1]>=thin[center+1]&&renderer.bloomDispatches()>0);frame.bloom.reset();
    auto bad=clear;bad.volume[0]=2;rejects([&]{renderer.draw(glass,identity,identity,bad);});bad=clear;bad.volume[1]=-1;rejects([&]{renderer.draw(glass,identity,identity,bad);});bad=clear;bad.volume[0]=NAN;rejects([&]{renderer.draw(glass,identity,identity,bad);});
    renderer.begin({});assert(renderer.transmissionTextureBytes()==0&&renderer.bloomTextureBytes()==0);rejects([&]{renderer.captureTransmission();});renderer.resize(80,48);renderer.begin(frame);renderer.captureTransmission();assert(renderer.transmissionTextureBytes()>0);renderer.resize(64,64);assert(renderer.transmissionTextureBytes()==0);renderer.begin({});
    return {{"thinBackground",true},{"iorThicknessPixel",true},{"roughMipPixel",true},{"hdrReuseWithoutBloomCompute",true},{"optionalBloomComposition",true},{"samplerLimitValidation",true},{"cropViewportScissor",true},{"reuseReleaseResize",true},{"validation",true},{"reuseSnapshotCopies",copies+3},{"automaticReadbacks",0}};
}
